/**
 * AD Sync Single-User Lambda
 *
 * Event-driven: invoked asynchronously when a user's attributes change
 * in Cognito (admin update, password reset, MFA change).
 *
 * Receives { tenantId, username, triggerEvent } and syncs that single
 * user between Cognito and AD.
 */

import { DynamoDBClient, GetItemCommand, QueryCommand } from '@aws-sdk/client-dynamodb';
import { SecretsManagerClient, GetSecretValueCommand } from '@aws-sdk/client-secrets-manager';
import { createRequire } from 'module';

const require = createRequire(import.meta.url);
const { buildConfig } = require('../../../../../CognitoAdSync/config');
const { syncSingleUser } = require('../../../../../CognitoAdSync/sync-engine');

const dynamodb = new DynamoDBClient({});
const secrets = new SecretsManagerClient({});

export const handler = async (event) => {
  const { tenantId, username, triggerEvent } = event;
  const timestamp = new Date().toISOString();

  console.log(JSON.stringify({
    level: "DEBUG", event: "SINGLE_USER_INVOKED",
    tenantId, username, triggerEvent, timestamp,
  }));

  if (!tenantId || !username) {
    console.error(JSON.stringify({
      level: "ERROR", event: "MISSING_PARAMS",
      message: "tenantId and username required", tenantId, username,
    }));
    return { statusCode: 400, body: { error: "tenantId and username required" } };
  }

  try {
    // 1. Load AD sync config
    const configItem = await dynamodb.send(new GetItemCommand({
      TableName: process.env.CONFIG_TABLE,
      Key: { id: { S: tenantId }, configtype: { S: "adSyncConfig" } },
    }));

    if (!configItem.Item?.value?.S) {
      console.log(JSON.stringify({ level: "INFO", event: "NO_CONFIG", tenantId, username, message: "No AD sync config — skipping" }));
      return { statusCode: 200, body: { skipped: true, reason: "no_config" } };
    }

    const adSyncConfig = JSON.parse(configItem.Item.value.S);

    if (!adSyncConfig.enabled) {
      console.log(JSON.stringify({ level: "INFO", event: "SYNC_DISABLED", tenantId, username }));
      return { statusCode: 200, body: { skipped: true, reason: "disabled" } };
    }

    // 2. Load tenant for User Pool ID
    const tenantResult = await dynamodb.send(new QueryCommand({
      TableName: process.env.TENANT_TABLE,
      KeyConditionExpression: "id = :id AND begins_with(sk, :sk_prefix)",
      ExpressionAttributeValues: {
        ":id": { S: `TENANT#${tenantId}` },
        ":sk_prefix": { S: "TENANT#" },
      },
      Limit: 1,
    }));

    const tenantItem = tenantResult.Items?.[0];
    if (!tenantItem?.userpool?.S) {
      console.error(JSON.stringify({ level: "ERROR", event: "TENANT_NOT_FOUND", tenantId }));
      return { statusCode: 404, body: { error: "tenant_not_found" } };
    }

    const userPoolId = tenantItem.userpool.S;

    // 3. Load AD credentials
    const secretResponse = await secrets.send(new GetSecretValueCommand({
      SecretId: `apersona/${tenantId}/ad-sync`,
    }));
    const adCredentials = JSON.parse(secretResponse.SecretString);

    // 4. Build config
    const config = buildConfig({
      tenantId,
      ldapProvider: adSyncConfig.ldapProvider,
      ldapUrl: adSyncConfig.ldapUrl,
      ldapBaseDN: adSyncConfig.ldapBaseDN,
      ldapPort: adSyncConfig.ldapPort,
      ldapBindDN: adCredentials.bindDN,
      ldapBindPassword: adCredentials.bindPassword,
      ldapGroupBaseDN: adSyncConfig.ldapGroupBaseDN,
      ldapTlsRejectUnauth: adSyncConfig.ldapTlsRejectUnauth,
      cognitoUserPoolId: userPoolId,
      fieldMappings: adSyncConfig.fieldMappings,
      logLevel: adSyncConfig.logLevel || "DEBUG",
    });

    console.log(JSON.stringify({
      level: "DEBUG", event: "CONFIG_BUILT", tenantId, username, userPoolId,
      ldapUrl: adSyncConfig.ldapUrl, triggerEvent,
    }));

    // 5. Run single-user sync
    const result = await syncSingleUser(config, username);

    console.log(JSON.stringify({
      level: "INFO", event: "SINGLE_USER_COMPLETE",
      tenantId, username, triggerEvent, result,
    }));

    return { statusCode: 200, body: result };
  } catch (err) {
    console.error(JSON.stringify({
      level: "ERROR", event: "SINGLE_USER_FAILED",
      tenantId, username, triggerEvent,
      error: err.message, stack: err.stack,
    }));
    return { statusCode: 500, body: { error: err.message, tenantId, username } };
  }
};
